import { test, expect } from '@playwright/test';
import path from 'node:path';
import { EXPERT_PATH } from '../helpers/expert';

test.use({ storageState: path.join(__dirname, '../../../auth/user2.json') });

test.describe('Экран «חוקי זיהוי» — доступ', () => {
  test('Обычный родитель: в «חשבון» нет «חוקי זיהוי», прямой заход на /account/expert закрыт #89216b @desktop @prod-safe', async ({ page }) => {
    // 1. «חשבון»: список загружен (есть соседние строки), строки «חוקי זיהוי» нет — AC1
    await page.goto('/account');
    await expect(page.getByText('מוצרים לבריכה', { exact: true }).filter({ visible: true })).toBeVisible();
    await expect(page.getByText('יציאה מהחשבון', { exact: true }).filter({ visible: true })).toBeVisible();
    await expect(page.getByText('חוקי זיהוי', { exact: true }).filter({ visible: true })).toHaveCount(0);

    // 2. Прямой адрес: сообщение о доступе, полей и кнопки сохранения нет — «מי רואה? רק חשבונות שהוגדרו כאיש מקצוע»
    await page.goto(EXPERT_PATH);
    await expect(page.getByText(/המסך הזה פתוח רק לאיש המקצוע של המערכת/).filter({ visible: true })).toBeVisible();
    await expect(page.getByText('שמירת החוקים', { exact: true }).filter({ visible: true })).toHaveCount(0);
    await expect(page.getByText('גרסה נוכחית:', { exact: false }).filter({ visible: true })).toHaveCount(0);
    await expect(page.locator('input:visible, textarea:visible')).toHaveCount(0);
  });
});
